function arrayBufferToBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary);}
function base64ToBytes(s){const bin=atob(s);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return bytes;}
function requestShim(raw){let body=raw.body?.data;if(raw.body?.encoding==='base64')body=base64ToBytes(raw.body.data||'');return{method:raw.method,path:raw.path,url:raw.url,originalUrl:raw.url,headers:raw.headers||{},query:raw.query||{},params:raw.params||{},body,get(name){const key=Object.keys(this.headers).find((k)=>k.toLowerCase()===String(name).toLowerCase());return key?this.headers[key]:undefined;},header(name){return this.get(name);}};}
async function runHandlers(handlers,req,res){let index=-1;const next=async(err)=>{if(err)throw err;index++;const fn=handlers[index];if(!fn)return;let called=false;const p=fn(req,res,(e)=>{called=true;return next(e);});if(p&&typeof p.then==='function')await p;if(!called&&fn.length>=3&&!res.ended)return;};await next();}
function zodToJson(z){if(!z)return{};const d=z._def||z.def||{};let type=d.typeName||d.type||z.constructor?.name||'';type=String(type).replace(/^Zod/,'').toLowerCase();if(type.includes('optional')||type.includes('default')||type.includes('nullable')||type.includes('catch'))return zodToJson(d.innerType||d.type||d.schema);if(type.includes('string'))return{type:'string',description:z.description};if(type.includes('number'))return{type:'number',description:z.description};if(type.includes('boolean'))return{type:'boolean',description:z.description};if(type.includes('bigint'))return{type:'integer',description:z.description};if(type.includes('literal'))return{const:d.value??d.values?.[0]};if(type.includes('enum')){const values=d.values||Object.values(d.entries||{});return{type:'string',enum:[...new Set(values.filter((v)=>typeof v==='string'))]};}if(type.includes('array'))return{type:'array',items:zodToJson(d.type||d.element)};if(type.includes('union'))return{anyOf:(d.options||[]).map(zodToJson)};if(type.includes('record'))return{type:'object',additionalProperties:zodToJson(d.valueType||d.valueSchema)};if(type.includes('object')){const shape=typeof d.shape==='function'?d.shape():d.shape||z.shape||{};const properties={},required=[];for(const[k,v]of Object.entries(shape)){properties[k]=zodToJson(v);let optional=false;try{optional=typeof v.isOptional==='function'&&v.isOptional();}catch{}if(!optional)required.push(k);}return{type:'object',properties,required,additionalProperties:false};}return{};}
function schemaRecordToJson(record){const properties={},required=[];for(const[k,v]of Object.entries(record||{})){properties[k]=zodToJson(v);let optional=false;try{optional=typeof v.isOptional==='function'&&v.isOptional();}catch{}if(!optional)required.push(k);}return{type:'object',properties,required,additionalProperties:false};}

module.exports=class IgnisLocalRestApiBridge extends Plugin{
 async onload(){const ignis=window.__ignis;if(!ignis?.ws?.channel){console.warn('[obsidian-local-rest-api] Ignis websocket API unavailable');return;}this.channel=ignis.ws.channel(CHANNEL);this.routes=new Map();this.tools=new Map();this.extensionHandles=new Map();this.unsubRpc=this.channel.subscribe('rpc-request',(msg)=>this.handleRpc(msg));this.previousRegistryValue=this.app.plugins?.plugins?.['obsidian-local-rest-api'];if(this.app.plugins?.plugins)this.app.plugins.plugins['obsidian-local-rest-api']=this;this.unsubState=ignis.ws.onStateChange?.((state)=>{if(state==='open')this.announceAll();});this.heartbeat=setInterval(()=>this.announceHeartbeat(),10000);this.registerInterval(this.heartbeat);setTimeout(()=>this.announceAll(),0);console.log('[obsidian-local-rest-api] Ignis browser companion loaded');}
 announceHeartbeat(){this.channel?.send('bridge-heartbeat',{vaultId:window.__ignis?.vault?.id});}
 announceAll(){this.channel?.send('bridge-online',{vaultId:window.__ignis?.vault?.id});for(const entry of this.routes.values())this.sendRouteRegistration(entry);for(const entry of this.tools.values())this.sendToolRegistration(entry);}
 sendRouteRegistration(r){this.channel.send('extension-route-register',{vaultId:window.__ignis?.vault?.id,routeId:r.routeId,extensionId:r.extensionId,extensionName:r.extensionName,path:r.path,method:r.method,authenticated:r.authenticated});}
 sendToolRegistration(t){this.channel.send('extension-mcp-register',{vaultId:window.__ignis?.vault?.id,toolId:t.toolId,extensionId:t.extensionId,extensionName:t.extensionName,name:t.name,description:t.description,inputSchema:t.inputSchema,annotations:t.annotations});}
 async handleRpc(msg){const reply=(ok,value)=>this.channel.send('rpc-response',{id:msg.id,vaultId:window.__ignis?.vault?.id,ok,...(ok?{result:value}:{error:value instanceof Error?value.message:String(value),statusCode:value?.statusCode})});try{reply(true,await this.dispatch(msg.method,msg.params||{}));}catch(e){console.error('[obsidian-local-rest-api] RPC failed',msg.method,e);reply(false,e);}}
 file(path){const f=this.app.vault.getAbstractFileByPath(String(path||''));if(!f||!('extension'in f))throw Object.assign(new Error(`File not found: ${path}`),{statusCode:404});return f;}
 activeFile(){const f=this.app.workspace.getActiveFile();if(!f)throw Object.assign(new Error('No active file'),{statusCode:404});return f;}
 async dispatch(method,p){
  if(method==='active.getPath')return{path:this.activeFile().path};
  if(method==='metadata.file'){const file=this.file(p.path);const cache=this.app.metadataCache.getFileCache(file)||{};const fm={...(cache.frontmatter||{})};delete fm.position;const direct=(cache.tags||[]).filter(Boolean).map((t)=>t.tag);const fmTags=Array.isArray(fm.tags)?fm.tags.filter((t)=>typeof t==='string'):[];const tags=[...fmTags,...direct].filter(Boolean).map((t)=>String(t).replace(/^#/,''));const unique=[...new Set(tags)];const backlinks=[];for(const[source,targets]of Object.entries(this.app.metadataCache.resolvedLinks||{}))if(targets&&Object.prototype.hasOwnProperty.call(targets,file.path))backlinks.push(source);return{tags:unique,frontmatter:fm,stat:file.stat,path:file.path,content:p.includeContent===false?'':await this.app.vault.cachedRead(file),links:Object.keys(this.app.metadataCache.resolvedLinks?.[file.path]||{}),backlinks,unresolvedLinks:Object.keys(this.app.metadataCache.unresolvedLinks?.[file.path]||{})};}
  if(method==='metadata.tags'){const counts={};for(const file of this.app.vault.getMarkdownFiles()){const cache=this.app.metadataCache.getFileCache(file);const tags=cache?getAllTags(cache):null;if(!tags)continue;for(const raw of tags){const tag=raw.replace(/^#/,'');counts[tag]=(counts[tag]||0)+1;const parts=tag.split('/');for(let i=1;i<parts.length;i++){const parent=parts.slice(0,i).join('/');counts[parent]=(counts[parent]||0)+1;}}}return{tags:Object.entries(counts).filter(([name])=>name).map(([name,count])=>({name,count})).sort((a,b)=>a.name.localeCompare(b.name))};}
  if(method==='search.simple'){const query=String(p.query||'');const contextLength=Number(p.contextLength??100);const search=prepareSimpleSearch(query);const results=[];for(const file of this.app.vault.getMarkdownFiles()){const content=await this.app.vault.cachedRead(file);const prefix=file.basename+'\n\n';const r=search(prefix+content);if(!r)continue;const offset=prefix.length,matches=[];for(const mt of r.matches){if(mt[0]<offset&&mt[1]<=offset)matches.push({match:{start:mt[0],end:Math.min(mt[1],file.basename.length),source:'filename'},context:file.basename});else if(mt[0]>=offset){const s=mt[0]-offset,e=mt[1]-offset;matches.push({match:{start:s,end:e,source:'content'},context:content.slice(Math.max(0,s-contextLength),Math.min(content.length,e+contextLength))});}}results.push({filename:file.path,score:r.score,matches});}results.sort((a,b)=>(b.score||0)-(a.score||0));return{results};}
  if(method==='render.markdown'){const doc=(typeof activeDocument!=='undefined'&&activeDocument)||document;const el=doc.createElement('div');const component=new Component();component.load();try{await MarkdownRenderer.render(this.app,String(p.markdown||''),el,String(p.path||''),component);return{html:el.innerHTML};}finally{component.unload();}}
  if(method==='file.delete'){const file=this.file(p.path);if(p.permanent)await this.app.vault.delete(file,true);else if(this.app.fileManager?.trashFile)await this.app.fileManager.trashFile(file);else await this.app.vault.delete(file);return{path:p.path,deleted:true,permanent:!!p.permanent};}
  if(method==='file.move'){const file=this.file(p.path);const destination=this.destinationPath(file.path,p.destination);const exists=this.app.vault.getAbstractFileByPath(destination);if(exists&&!p.allowOverwrite)throw Object.assign(new Error('Destination file already exists.'),{statusCode:409});if(exists&&p.allowOverwrite)await this.app.vault.delete(exists,true);await this.ensureFolders(destination);if(this.app.fileManager?.renameFile)await this.app.fileManager.renameFile(file,destination);else await this.app.vault.rename(file,destination);return{oldPath:p.path,newPath:destination};}
  if(method==='file.copy'){const file=this.file(p.path);const destination=this.destinationPath(file.path,p.destination);const exists=this.app.vault.getAbstractFileByPath(destination);if(exists&&!p.allowOverwrite)throw Object.assign(new Error('Destination file already exists.'),{statusCode:409});if(exists&&p.allowOverwrite)await this.app.vault.delete(exists,true);await this.ensureFolders(destination);if(this.app.vault.copy)await this.app.vault.copy(file,destination);else await this.app.vault.adapter.writeBinary(destination,await this.app.vault.readBinary(file));return{sourcePath:p.path,newPath:destination};}
  if(method==='commands.list')return Object.values(this.app.commands?.commands||{}).map((c)=>({id:c.id,name:c.name})).sort((a,b)=>a.name.localeCompare(b.name));
  if(method==='commands.execute'){const id=String(p.commandId||'');if(!this.app.commands?.commands?.[id])throw Object.assign(new Error(`Command not found: ${id}`),{statusCode:404});this.app.commands.executeCommandById(id);return{commandId:id};}
  if(method==='open'){await this.app.workspace.openLinkText(String(p.path||''),'',!!p.newLeaf);return{path:p.path,opened:true};}
  if(method==='extension.route'){const route=this.routes.get(p.routeId);if(!route)throw new Error(`Extension route not registered: ${p.routeId}`);const req=requestShim(p.request||{}),res=new ResponseShim();await runHandlers(route.handlers,req,res);return res.serialize();}
  if(method==='extension.mcp'){const t=this.tools.get(p.toolId);if(!t)throw new Error(`Extension MCP tool not registered: ${p.toolId}`);return await t.callback(p.args||{});}
  throw new Error(`Unknown browser RPC method: ${method}`);
 }
 destinationPath(source,destination){let dest=String(destination||'').replace(/\\/g,'/');if(dest.endsWith('/'))dest+=source.split('/').pop();return dest.replace(/^\/+/, '');}
 async ensureFolders(filePath){const parts=String(filePath).split('/').slice(0,-1);let cur='';for(const p of parts){cur=cur?cur+'/'+p:p;if(!this.app.vault.getAbstractFileByPath(cur)){try{await this.app.vault.createFolder(cur);}catch{}}}}
 getPublicApi(pluginManifest){if(!pluginManifest?.id||!pluginManifest?.name||!pluginManifest?.version)throw new Error('PluginManifest must include id, name, and version.');const extensionId=pluginManifest.id;const handleId=extensionId+':'+Math.random().toString(36).slice(2);const ownedRoutes=new Set(),ownedTools=new Set();let unregistered=false;const assert=()=>{if(unregistered)throw new Error('Routes cannot be added after API extension has been unregistered.');};const addRoute=(path,authenticated)=>{assert();return this.makeRoute(pluginManifest,path,authenticated,ownedRoutes);};const api={apiVersion:2,addRoute:(p)=>addRoute(p,true),addPublicRoute:(p)=>{if(['/','/openapi.yaml','/obsidian-local-rest-api.crt'].includes(p))throw new Error(`Cannot register a public route at "${p}" — reserved.`);return addRoute(p,false);},addMcpTool:(name,description,schema,callback,annotations)=>{assert();if([...this.tools.values()].some((t)=>t.name===name))throw new Error(`MCP tool already registered: ${name}`);const toolId=extensionId+':tool:'+Math.random().toString(36).slice(2);const entry={toolId,extensionId,extensionName:pluginManifest.name,name,description,inputSchema:schemaRecordToJson(schema),callback,annotations:annotations||{}};this.tools.set(toolId,entry);ownedTools.add(toolId);this.sendToolRegistration(entry);},unregister:()=>{if(unregistered)return;unregistered=true;for(const id of ownedRoutes){this.routes.delete(id);this.channel.send('extension-route-unregister',{vaultId:window.__ignis?.vault?.id,routeId:id});}for(const id of ownedTools){this.tools.delete(id);this.channel.send('extension-mcp-unregister',{vaultId:window.__ignis?.vault?.id,toolId:id});}this.channel.send('extension-unregister',{vaultId:window.__ignis?.vault?.id,extensionId});this.extensionHandles.delete(handleId);}};this.extensionHandles.set(handleId,api);return api;}
 makeRoute(manifest,path,authenticated,owned){const route={};for(const method of['get','post','put','patch','delete','head','options','all'])route[method]=(...handlers)=>{if(!handlers.length||handlers.some((h)=>typeof h!=='function'))throw new Error('Route handlers must be functions');const routeId=manifest.id+':route:'+Math.random().toString(36).slice(2);const entry={routeId,extensionId:manifest.id,extensionName:manifest.name,path,method,authenticated,handlers};this.routes.set(routeId,entry);owned.add(routeId);this.sendRouteRegistration(entry);return route;};return route;}
 onunload(){try{this.channel?.send('bridge-offline',{vaultId:window.__ignis?.vault?.id});}catch{}this.unsubRpc?.();this.unsubState?.();if(this.app.plugins?.plugins?.['obsidian-local-rest-api']===this){if(this.previousRegistryValue)this.app.plugins.plugins['obsidian-local-rest-api']=this.previousRegistryValue;else delete this.app.plugins.plugins['obsidian-local-rest-api'];}this.routes?.clear();this.tools?.clear();console.log('[obsidian-local-rest-api] Ignis browser companion unloaded');}
};
